/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNonNegativeNumber = require( '@stdlib/assert/is-nonnegative-number' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the tics spacing of w axis.
* Note: space require between each tics label in axis is in control of the specific plot package.
*
* @private
* @param {Number} value - tics spacing
* @throws {TypeError} must be a non negative number
*/
function set( value ) {
	if ( !isNonNegativeNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` non negative number is expected. Value: `%s`.', 'w-tic-spacing', value ) );
	}
	if ( this._axisDataObjs[ 3 ].ticsSpacing !== value ) {
		this._axisDataObjs[ 3 ].ticsSpacing = value;
		if ( !this._quite ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
